import math
import time

TIMEOUT_MS = 250.0
CENTER = 0.5

def _timestamps(value):
    if isinstance(value, list):
        out = []
        for item in value:
            out.extend(_timestamps(item))
        return out
    if not isinstance(value, dict):
        return []
    raw = value.get('receivedAtMs', value.get('timestampMs'))
    if isinstance(raw, bool) or raw is None:
        return []
    try:
        number = float(raw)
    except (TypeError, ValueError, OverflowError):
        return []
    return [number] if math.isfinite(number) else []

def _number(value):
    if isinstance(value, bool) or value is None:
        return None
    try:
        number = float(value)
    except (TypeError, ValueError, OverflowError):
        return None
    return number if math.isfinite(number) else None

def onStart(ctx):
    ctx.locals['lastValid'] = CENTER
    ctx.locals['state'] = 'idle'

def onMsg(ctx, inputs):
    now_ms = time.time() * 1000.0
    timestamps = _timestamps(inputs.get('heartbeat'))
    age_ms = max(0.0, now_ms - min(timestamps)) if timestamps else None
    incoming = _number(inputs.get('value'))
    fresh = age_ms is not None and age_ms <= TIMEOUT_MS and incoming is not None
    if fresh:
        output = max(0.0, min(1.0, incoming))
        ctx.locals['lastValid'] = output
        state = 'active'
    elif age_ms is not None and age_ms <= TIMEOUT_MS:
        output = float(ctx.locals.get('lastValid', CENTER))
        state = 'holding'
    else:
        output = CENTER
        state = 'releasing'
    ctx.locals['state'] = state
    return {'outputs': {'safeValue': output, 'status': {'state': state, 'fresh': fresh, 'ageMs': age_ms, 'timeoutMs': TIMEOUT_MS, 'center': CENTER}}}
